As usual we use the facts from Section~ef{Preliminaries} without further reference. The lemma is trivial if $m = 1$, so we assume that $m \geq 2$. Let $a \in M$ and let \[ \crd(a) = \{b_1, \ldots, b_m\}. \] Towards a contradiction, suppose that there is a nontrivial permutation $\pi$ of $\{1, \ldots, m\}$ such that  egin{equation} 	p_\mcR(b_1, \ldots, b_m) = 	p_\mcR(b_{\pi(1)}, \ldots, b_{\pi(m)}). \end{equation} To simplify notation and witout loss of generality,  egin{equation} 	ext{ we assume that $\pi(1) = 2$. } \end{equation} From~(ef{the permuted sequence has the same type}) and~(ef{pi(1) equals 2}) we get \[ 	p_\mcR(b_1) = 	p_\mcR(b_2). \] As $\mcR$ is a binary random structure we can argue as in Remark~ef{remarks about binary random structures} (with $n = 3$, $p_{1, 2}(x_1, x_2) = 	p_\mcR(b_1, b_2)$, $p_{1, 3}(x_1, x_3) = 	p_\mcR(b_1, b_2)$ and $p_{2, 3}(x_2, x_3) = 	p_\mcR(b_1, b_2)$) and find $b'_2 \in R$ such that \[ 	p_\mcR(b_1, b'_2) \ = \ 	p_\mcR(b_1, b_2) \ = \ 	p_\mcR(b_2, b'_2). \] If $m > 2$, then, by using that $\mcR$ is a random structure again, we find {\em distinct} elements $b'_3, \ldots, b'_m, b''_3, \ldots, b''_m \in R$ such that if we let  egin{equation} b'_1 = b_1, \ b''_1 = b_2, \ b''_2 = b'_2, \end{equation} then  egin{align} 	p_\mcR(b_1, b_2, \ldots, b_m) \ = \ 	p_\mcR(b'_1, b'_2, \ldots, b'_m) \ = \ 	p_\mcR(b''_1, b''_2, \ldots, b''_m). \end{align} 
oindent From~(ef{the permuted sequence has the same type}) and~(ef{the other sequences have the same type}) we get  egin{align} 	p_\mcR(b_1, b_2, \ldots, b_m) \ &= \ 	p_\mcR(b_{\pi(1)}, b_{\pi(2)}, \ldots, b_{\pi(m)}), \ 	p_\mcR(b'_1, b'_2, \ldots, b'_m) \ &= \ 	p_\mcR(b'_{\pi(1)}, b'_{\pi(2)}, \ldots, b'_{\pi(m)}) \quad 	ext{ and} 
onumber \ 	p_\mcR(b''_1, b''_2, \ldots, b''_m) \ &= \ 	p_\mcR(b''_{\pi(1)}, b''_{\pi(2)}, \ldots, b''_{\pi(m)}), 
onumber \end{align} Since $	p_\mcR(b_1) = 	p_\mcR(b_2) = 	p_\mcR(b'_2)$ and $\mcR$ is a binary random structure it follows from~(ef{the same type when the other sequences are permuted}) that there are $c_2, \ldots, c_m \in R \setminus \{b_1, \ldots, b_m, b'_1, \ldots, b'_m\}$ such that if $c_1 = b_1 (= b'_1)$, then  egin{align} 	p_\mcR(b_1, \ldots, b_m, c_1, \ldots, c_m) \ &= \ 	p_\mcR(b_{\pi(1)}, \ldots, b_{\pi(m)}, b''_1, \ldots, b''_m) \quad 	ext{ and} \ 	p_\mcR(b'_1, \ldots, b'_m, c_1, \ldots, c_m) \ &= \ 	p_\mcR(b'_{\pi(1)}, \ldots, b'_{\pi(m)}, b''_{\pi(1)}, \ldots, b''_{\pi(m)}). 
onumber \end{align} 
oindent Since $\mcC_1$ is a reduct of $\mcR$ we can replace `$	p_\mcR$' with `$	p_{\mcC_1}$' everywhere in~(ef{the other sequences have the same type}),~(ef{the same type when the other sequences are permuted}) and~(ef{equal types of some long sequences}). Moreover, as $\mcC_1$ is a canonically embedded structure of $\mcM\meq$, we can replace `$	p_{\mcC_1}$' with `$	p$' (which abbreviates `$	p_{\mcM\meq}$'), so altogether we get  egin{align} &	p(b_1, b_2, \ldots, b_m) \ = \ 	p(b'_1, b'_2, \ldots, b'_m) \ = \ 	p(b''_1, b''_2, \ldots, b''_m), \ &	p(b_1, b_2, \ldots, b_m) \ = \ 	p(b_{\pi(1)}, b_{\pi(2)}, \ldots, b_{\pi(m)}), 
onumber \ &	p(b'_1, b'_2, \ldots, b'_m) \ = \ 	p(b'_{\pi(1)}, b'_{\pi(2)}, \ldots, b'_{\pi(m)}), 
onumber \ &	p(b''_1, b''_2, \ldots, b''_m) \ = \ 	p(b''_{\pi(1)}, b''_{\pi(2)}, \ldots, b''_{\pi(m)}), 
onumber \ &	p(b_1, \ldots, b_m, c_1, \ldots, c_m) \ = \ 	p(b_{\pi(1)}, \ldots, b_{\pi(m)}, b''_1, \ldots, b''_m) \quad 	ext{ and} 
onumber \ &	p(b'_1, \ldots, b'_m, c_1, \ldots, c_m) \ = \ 	p(b'_{\pi(1)}, \ldots, b'_{\pi(m)}, b''_{\pi(1)}, \ldots, b''_{\pi(m)}). 
onumber \end{align} 
oindent In particular,~(ef{type identifications in Meq}) implies that $	p(c_1, \ldots, c_m) = 	p(b''_{\pi(1)}, \ldots, b''_{\pi(m)}) = 	p(b''_1, \ldots, b''_m) = 	p(b'_1, \ldots, b'_m) = 	p(b_1, \ldots, b_m)$. So, using the $\omega$-homogeneity of $\mcM\meq$, there is $a^* \in M$ such that \[ 	p(a^*, c_1, \ldots, c_m) \ = \ 	p(a, b_1, \ldots, b_m) \] and hence $\crd(a^*) = \{c_1, \ldots, c_m\}$. For the same reason there is $a' \in M$ such that \[ 	p(a', b'_1, \ldots, b'_m) \ = \ 	p(a, b_1, \ldots, b_m) \] and hence $\crd(a') = \{b'_1, \ldots, b'_m\}$. By the $\omega$-homogeneity of $\mcM\meq$ again and~(ef{type identifications in Meq}), there are $a_0, a'', a'_0, a''_0 \in M$ such that  egin{align} 	p(a, b_1, \ldots, b_m, a^*, c_1, \ldots, c_m) \ &= \ 	p(a_0, b_{\pi(1)}, \ldots, b_{\pi(m)}, a'', b''_1, \ldots, b''_m) \ \ 	ext{and} \ 	p(a', b'_1, \ldots, b'_m, a^*, c_1, \ldots, c_m) \ &= \ 	p(a'_0, b'_{\pi(1)}, \ldots, b'_{\pi(m)}, a''_0, b''_{\pi(1)}, \ldots, b''_{\pi(m)}). 
onumber \end{align} Then $\crd(a_0) = \{b_1, \ldots, b_m\}$, $\crd(a'_0) = \{b'_1, \ldots, b'_m\}$ and $\crd(a'') = \crd(a''_0) = \{b''_1, \ldots, b''_m\}$. As the equivalence relation $\acl_\mcM(x) = \acl_\mcM(y)$ is assumed to be trivial it follows from Lemma~ef{every element is in dcl of its coordinates} that $a_0 = a$, $a'_0 = a'$ and $a''_0 = a''$. Therefore~(ef{the elements corresponding to a}) implies that  egin{align*} &	p(a, a'') = 	p(a, a^*) 	ext{ and } 	p(a', a'') = 	p(a', a^*), 	ext{ and hence} \ &	p_\mcM(a, a'') = 	p_\mcM(a, a^*) 	ext{ and } 	p_\mcM(a', a'') = 	p_\mcM(a', a^*). \end{align*} As $\mcM$ is a homogeneous and binary we get \[ 	p_\mcM(a, a', a'') = 	p_\mcM(a, a', a^*)\] and hence $	p(a, a', a'') = 	p(a, a', a^*)$. Since (by definition) $\crd(a) = \acl(a) \cap C_1$ and similarly for $a', a''$ and $a^*$, there are permutations $\sigma_1, \sigma_2, \sigma_3$ of $\{1, \ldots, m\}$ such that  egin{align} &	p(b_1, \ldots, b_m, b'_1, \ldots, b'_m, b''_1, \ldots, b''_m) \ = \ &	p(b_{\sigma_1(1)}, \ldots, b_{\sigma_1(m)}, b'_{\sigma_2(1)}, \ldots, b'_{\sigma_2(m)}, c_{\sigma_3(1)}, \ldots, c_{\sigma_3(m)}). 
onumber \end{align} We have \[ \{b_1, \ldots, b_m\} \cap \{b'_1, \ldots, b'_m\} \cap \{c_1, \ldots, c_m\} \ 
eq \ \es \] because $b_1 = b'_1 = c_1$ belongs to this intersection, while \[ \{b_1, \ldots, b_m\} \cap \{b'_1, \ldots, b'_m\} \cap \{b''_1, \ldots, b''_m\} \ = \ \es \] by the choice of these elements. This contradicts~(ef{the long sequences have the same type}).

From~(ef{the permuted sequence has the same type}) and~(ef{the other sequences have the same type}) we get  egin{align} 	p_\mcR(b_1, b_2, \ldots, b_m) \ &= \ 	p_\mcR(b_{\pi(1)}, b_{\pi(2)}, \ldots, b_{\pi(m)}), \ 	p_\mcR(b'_1, b'_2, \ldots, b'_m) \ &= \ 	p_\mcR(b'_{\pi(1)}, b'_{\pi(2)}, \ldots, b'_{\pi(m)}) \quad 	ext{ and} 
onumber \ 	p_\mcR(b''_1, b''_2, \ldots, b''_m) \ &= \ 	p_\mcR(b''_{\pi(1)}, b''_{\pi(2)}, \ldots, b''_{\pi(m)}), 
onumber \end{align} Since $	p_\mcR(b_1) = 	p_\mcR(b_2) = 	p_\mcR(b'_2)$ and $\mcR$ is a binary random structure it follows from~(ef{the same type when the other sequences are permuted}) that there are $c_2, \ldots, c_m \in R \setminus \{b_1, \ldots, b_m, b'_1, \ldots, b'_m\}$ such that if $c_1 = b_1 (= b'_1)$, then  egin{align} 	p_\mcR(b_1, \ldots, b_m, c_1, \ldots, c_m) \ &= \ 	p_\mcR(b_{\pi(1)}, \ldots, b_{\pi(m)}, b''_1, \ldots, b''_m) \quad 	ext{ and} \ 	p_\mcR(b'_1, \ldots, b'_m, c_1, \ldots, c_m) \ &= \ 	p_\mcR(b'_{\pi(1)}, \ldots, b'_{\pi(m)}, b''_{\pi(1)}, \ldots, b''_{\pi(m)}). 
onumber \end{align}

Since $\mcC_1$ is a reduct of $\mcR$ we can replace `$	p_\mcR$' with `$	p_{\mcC_1}$' everywhere in~(ef{the other sequences have the same type}),~(ef{the same type when the other sequences are permuted}) and~(ef{equal types of some long sequences}). Moreover, as $\mcC_1$ is a canonically embedded structure of $\mcM\meq$, we can replace `$	p_{\mcC_1}$' with `$	p$' (which abbreviates `$	p_{\mcM\meq}$'), so altogether we get  egin{align} &	p(b_1, b_2, \ldots, b_m) \ = \ 	p(b'_1, b'_2, \ldots, b'_m) \ = \ 	p(b''_1, b''_2, \ldots, b''_m), \ &	p(b_1, b_2, \ldots, b_m) \ = \ 	p(b_{\pi(1)}, b_{\pi(2)}, \ldots, b_{\pi(m)}), 
onumber \ &	p(b'_1, b'_2, \ldots, b'_m) \ = \ 	p(b'_{\pi(1)}, b'_{\pi(2)}, \ldots, b'_{\pi(m)}), 
onumber \ &	p(b''_1, b''_2, \ldots, b''_m) \ = \ 	p(b''_{\pi(1)}, b''_{\pi(2)}, \ldots, b''_{\pi(m)}), 
onumber \ &	p(b_1, \ldots, b_m, c_1, \ldots, c_m) \ = \ 	p(b_{\pi(1)}, \ldots, b_{\pi(m)}, b''_1, \ldots, b''_m) \quad 	ext{ and} 
onumber \ &	p(b'_1, \ldots, b'_m, c_1, \ldots, c_m) \ = \ 	p(b'_{\pi(1)}, \ldots, b'_{\pi(m)}, b''_{\pi(1)}, \ldots, b''_{\pi(m)}). 
onumber \end{align}
